import Testing
import Foundation
import OmFileFormatC

/// Wire-format fixtures, pinned after the 64-bit SIMD lane-order fix.
/// Encoders must write zero unused tail bits; historical nonzero padding is
/// retained separately below as decode-only compatibility fixtures.
/// Expected bytes are literals, never generated by a codec during tests.
/// Do not refresh them merely to make a failure pass: investigate compatibility
/// first. These fixtures cover selected encodings, not every possible stream.
@Suite struct CompressedBytesCompatibilityTests {
    enum Codec: Int, Sendable { case delta, zigzag, pfor, pforSIMD, fpx }
    enum Pattern: Sendable {
        case tail, blocksAndTail, exceptions, seedOrConstant, zeros
        case boundary, packedWidth(Int), literal([UInt64])
        case wraparound, exceptionEdges, denseExceptions, floatEdges
    }

    struct Fixture: Sendable, CustomTestStringConvertible {
        let bits: Int
        let codec: Codec
        let pattern: Pattern
        let count: Int
        let hex: String
        var label: String = ""
        var testDescription: String { "\(codec)\(bits)/\(label.isEmpty ? String(describing: pattern) : label)/n=\(count)" }

        // Values for FPX are IEEE bit patterns so signed zero and NaN payloads
        // are compared exactly, without floating-point equality or arithmetic.
        var values: [UInt64] {
            if case .literal(let values) = pattern {
                precondition(values.count == count)
                return values
            }
            let mask = UInt64.max >> (64 - bits)
            var v: UInt64 = 0
            return (0..<count).map { i in
                switch pattern {
                case .tail:
                    v = codec == .zigzag
                        ? UInt64(10 + (i % 2 == 1 ? (i + 1) / 2 : -i / 2))
                        : UInt64(10 + i * (i + 1) / 2)
                case .blocksAndTail:
                    v = codec == .delta ? v + UInt64(i % 7) : UInt64(i % 8)
                case .exceptions:
                    if codec == .fpx {
                        let floatBits: [UInt64] = [0, 0x80000000, 0x3f800000, 0x3fc00000,
                                                   0xc0000000, 0x7f800000, 0xff800000, 0x7fc12345]
                        let doubleBits: [UInt64] = [0, 0x8000000000000000, 0x3ff0000000000000, 0x3ff8000000000000,
                                                    0xc000000000000000, 0x7ff0000000000000, 0xfff0000000000000, 0x7ff8123456789abc]
                        v = bits == 32 ? floatBits[i] : doubleBits[i]
                    } else if codec == .delta || codec == .zigzag {
                        v += i == 64 ? UInt64(1) << (bits - 2) : 1
                    } else {
                        v = i == 64 ? UInt64(1) << (bits - 2) : UInt64(i % 4)
                    }
                case .seedOrConstant: v = mask
                case .zeros: v = 0
                case .boundary: v = UInt64(codec == .delta ? i / 3 : i % 5)
                case .packedWidth(let width):
                    v = ((UInt64(i) &* 0x9e3779b97f4a7c15) ^ 0xd1b54a32d192ed03) & (UInt64.max >> (64 - width))
                case .wraparound: v = (mask - 2) &+ UInt64(i * 3)
                case .exceptionEdges, .denseExceptions:
                    let predicted = codec == .delta || codec == .zigzag
                    if predicted && i == 0 {
                        v = mask - 2
                        break
                    }
                    let j = predicted ? i - 1 : i
                    let exceptional: Bool
                    if case .exceptionEdges = pattern {
                        exceptional = [0, 1, 62, 63, 64, 65, 126, 127].contains(j)
                    } else {
                        exceptional = j % 3 == 0
                    }
                    let step = exceptional ? UInt64(1) << (bits - 2) : UInt64(j % 4)
                    v = predicted ? (v &+ step) & mask : step
                case .floatEdges:
                    let floatBits: [UInt64] = [0, 0x80000000, 1, 0x80000001, 0x007fffff, 0x00800000,
                        0x3f800000, 0xbf800000, 0x7f7fffff, 0xff7fffff, 0x7f800000, 0xff800000,
                        0x7fc00001, 0x7fc12345, 0xffc54321, 0x7f800001]
                    let doubleBits: [UInt64] = [0, 0x8000000000000000, 1, 0x8000000000000001,
                        0x000fffffffffffff, 0x0010000000000000, 0x3ff0000000000000, 0xbff0000000000000,
                        0x7fefffffffffffff, 0xffefffffffffffff, 0x7ff0000000000000, 0xfff0000000000000,
                        0x7ff8000000000001, 0x7ff8123456789abc, 0xfff8abcdef012345, 0x7ff0000000000001]
                    v = bits == 32 ? floatBits[i % floatBits.count] : doubleBits[i % doubleBits.count]
                case .literal: preconditionFailure("Handled before building values")
                }
                return v & mask
            }
        }

        var compressed: [UInt8] {
            let chars = Array(hex.filter { !$0.isWhitespace }.utf8)
            precondition(chars.count % 2 == 0)
            func nibble(_ c: UInt8) -> UInt8 {
                precondition((48...57).contains(c) || (97...102).contains(c))
                return c <= 57 ? c - 48 : c - 97 + 10
            }
            return stride(from: 0, to: chars.count, by: 2).map { nibble(chars[$0]) << 4 | nibble(chars[$0 + 1]) }
        }
    }

