    // TurboPFor's original entry points require caller padding. Use aligned
    // storage for typed C accesses, with deterministic padding outside the data.
    private func valueBytes(_ f: Fixture) -> [UInt8] {
        f.values.flatMap { value -> [UInt8] in
            var littleEndian = value.littleEndian
            return withUnsafeBytes(of: &littleEndian) { Array($0.prefix(f.bits / 8)) }
        }
    }

    private func encode(_ f: Fixture, _ input: UnsafeMutableRawPointer, _ output: UnsafeMutablePointer<UInt8>) -> Int {
        switch (f.bits, f.codec) {
        case (8, .delta): return p4ndenc8(input.assumingMemoryBound(to: UInt8.self), f.count, output)
        case (8, .zigzag): return p4nzenc8(input.assumingMemoryBound(to: UInt8.self), f.count, output)
        case (8, .pfor): return p4nenc8(input.assumingMemoryBound(to: UInt8.self), f.count, output)
        case (16, .delta): return p4ndenc128v16(input.assumingMemoryBound(to: UInt16.self), f.count, output)
        case (16, .zigzag): return p4nzenc128v16(input.assumingMemoryBound(to: UInt16.self), f.count, output)
        case (16, .pfor): return p4nenc16(input.assumingMemoryBound(to: UInt16.self), f.count, output)
        case (16, .pforSIMD): return p4nenc128v16(input.assumingMemoryBound(to: UInt16.self), f.count, output)
        case (32, .delta): return p4ndenc128v32(input.assumingMemoryBound(to: UInt32.self), f.count, output)
        case (32, .zigzag): return p4nzenc128v32(input.assumingMemoryBound(to: UInt32.self), f.count, output)
        case (32, .pfor): return p4nenc32(input.assumingMemoryBound(to: UInt32.self), f.count, output)
        case (32, .pforSIMD): return p4nenc128v32(input.assumingMemoryBound(to: UInt32.self), f.count, output)
        case (32, .fpx): return fpxenc32(input.assumingMemoryBound(to: UInt32.self), f.count, output, 0)
        case (64, .delta): return p4ndenc64(input.assumingMemoryBound(to: UInt64.self), f.count, output)
        case (64, .zigzag): return p4nzenc64(input.assumingMemoryBound(to: UInt64.self), f.count, output)
        case (64, .pfor): return p4nenc64(input.assumingMemoryBound(to: UInt64.self), f.count, output)
        case (64, .pforSIMD): return p4nenc128v64(input.assumingMemoryBound(to: UInt64.self), f.count, output)
        case (64, .fpx): return fpxenc64(input.assumingMemoryBound(to: UInt64.self), f.count, output, 0)
        default: preconditionFailure("Unsupported fixture codec")
        }
    }

    private func decode(_ f: Fixture, _ input: UnsafeMutablePointer<UInt8>, _ output: UnsafeMutableRawPointer) -> Int {
        switch (f.bits, f.codec) {
        case (8, .delta): return p4nddec8(input, f.count, output.assumingMemoryBound(to: UInt8.self))
        case (8, .zigzag): return p4nzdec8(input, f.count, output.assumingMemoryBound(to: UInt8.self))
        case (8, .pfor): return p4ndec8(input, f.count, output.assumingMemoryBound(to: UInt8.self))
        case (16, .delta): return p4nddec128v16(input, f.count, output.assumingMemoryBound(to: UInt16.self))
        case (16, .zigzag): return p4nzdec128v16(input, f.count, output.assumingMemoryBound(to: UInt16.self))
        case (16, .pfor): return p4ndec16(input, f.count, output.assumingMemoryBound(to: UInt16.self))
        case (16, .pforSIMD): return p4ndec128v16(input, f.count, output.assumingMemoryBound(to: UInt16.self))
        case (32, .delta): return p4nddec128v32(input, f.count, output.assumingMemoryBound(to: UInt32.self))
        case (32, .zigzag): return p4nzdec128v32(input, f.count, output.assumingMemoryBound(to: UInt32.self))
        case (32, .pfor): return p4ndec32(input, f.count, output.assumingMemoryBound(to: UInt32.self))
        case (32, .pforSIMD): return p4ndec128v32(input, f.count, output.assumingMemoryBound(to: UInt32.self))
        case (32, .fpx): return fpxdec32(input, f.count, output.assumingMemoryBound(to: UInt32.self), 0)
        case (64, .delta): return p4nddec64(input, f.count, output.assumingMemoryBound(to: UInt64.self))
        case (64, .zigzag): return p4nzdec64(input, f.count, output.assumingMemoryBound(to: UInt64.self))
        case (64, .pfor): return p4ndec64(input, f.count, output.assumingMemoryBound(to: UInt64.self))
        case (64, .pforSIMD): return p4ndec128v64(input, f.count, output.assumingMemoryBound(to: UInt64.self))
        case (64, .fpx): return fpxdec64(input, f.count, output.assumingMemoryBound(to: UInt64.self), 0)
        default: preconditionFailure("Unsupported fixture codec")
        }
    }

    @Test(arguments: fixtures + additionalFixtures)
    func encodingMatchesFixedBytes(_ f: Fixture) {
        let values = valueBytes(f)
        let input = UnsafeMutableRawPointer.allocate(byteCount: values.count + 64, alignment: 16)
        defer { input.deallocate() }
        input.initializeMemory(as: UInt8.self, repeating: 0, count: values.count + 64)
        values.withUnsafeBytes { input.copyMemory(from: $0.baseAddress!, byteCount: $0.count) }
        // Check both clean and reused output buffers. Only the reported bytes
        // belong to the stream; padding and scratch space are not snapshotted.
        for fill: UInt8 in [0, 0xa5] {
            var output = [UInt8](repeating: fill, count: f.count * 16 + 4096)
            let length = output.withUnsafeMutableBufferPointer { encode(f, input, $0.baseAddress!) }
            #expect(length == f.compressed.count)
            #expect(Array(output.prefix(length)) == f.compressed)
        }
    }

    @Test(arguments: fixtures + additionalFixtures)
    func decodingFixedBytes(_ f: Fixture) {
        var input = f.compressed + [UInt8](repeating: 0, count: 64)
        let expected = valueBytes(f)
        let output = UnsafeMutableRawPointer.allocate(byteCount: expected.count + 64, alignment: 16)
        defer { output.deallocate() }
        output.initializeMemory(as: UInt8.self, repeating: 0xa5, count: expected.count + 64)
        let consumed = input.withUnsafeMutableBufferPointer { decode(f, $0.baseAddress!, output) }
        #expect(consumed == f.compressed.count)
        #expect(Array(UnsafeRawBufferPointer(start: output, count: expected.count)) == expected)

        // The bounded OM decoders must accept the same historical bytes.
        if f.codec == .delta || f.codec == .zigzag || f.codec == .fpx {
            output.initializeMemory(as: UInt8.self, repeating: 0xa5, count: expected.count + 64)
            let bounded = input.withUnsafeBytes { src in
                f.codec == .fpx
                    ? om_fpx_decode(src.baseAddress, f.compressed.count, f.count, output, UInt32(f.bits))
                    : om_pfor_decode(src.baseAddress, f.compressed.count, f.count, output, UInt32(f.bits), f.codec == .zigzag)
            }
            #expect(bounded == f.compressed.count)
            #expect(Array(UnsafeRawBufferPointer(start: output, count: expected.count)) == expected)
        }
    }
}
